package lint

import "strings"

// RulebookMarkdownTable renders the current rule set (in declaration order,
// which also matches rules/api-guidelines.yaml) as the markdown table the
// README embeds between its RULEBOOK:START/END markers.
func RulebookMarkdownTable() string {
	var b strings.Builder
	b.WriteString("| id | severity | title |\n")
	b.WriteString("|---|---|---|\n")
	for _, r := range Rules() {
		b.WriteString("| " + r.ID + " | " + r.Severity + " | " + r.Title + " |\n")
	}
	return strings.TrimRight(b.String(), "\n")
}

const (
	rulebookStartMarker = "<!-- RULEBOOK:START (generated by `make docs`; do not hand-edit between these markers) -->"
	rulebookEndMarker   = "<!-- RULEBOOK:END -->"
)

// RenderReadme replaces the content between the rulebook markers in readme
// with the current, freshly-generated table.
func RenderReadme(readme string) (string, error) {
	start := strings.Index(readme, rulebookStartMarker)
	end := strings.Index(readme, rulebookEndMarker)
	if start == -1 || end == -1 || end < start {
		return "", errMarkersNotFound
	}
	start += len(rulebookStartMarker)
	return readme[:start] + "\n" + RulebookMarkdownTable() + "\n" + readme[end:], nil
}

var errMarkersNotFound = &markerError{}

type markerError struct{}

func (*markerError) Error() string {
	return "RULEBOOK:START/END markers not found in README.md"
}
